from dataclasses import dataclass

PRICES = {
    "$45": 45,
    "$60": 60,
    "$75": 75,
    "$90": 90,
}

@dataclass
class Price:
    value: int
    winner: str = None
    spider: str = None

@dataclass
class Winner:
    name: str
    price: int = None
    spider: str = None

@dataclass
class Spider:
    name: str
    price: int = None
    winner: str = None

def clue0(Prices, Winners, Spiders):
    """Freddie's purchase cost 15 dollars more than the cart spider."""
    freddie_price = Winners["Freddie"].price
    cart_spider_price = Spiders["cart spider"].price
    return freddie_price == cart_spider_price + 15

def clue1(Prices, Winners, Spiders):
    """Of the darkback and the cart spider, one sold for $60 and the other was won by Vicky."""
    darkback_price = Spiders["darkback"].price
    darkback_winner = Spiders["darkback"].winner
    cart_spider_price = Spiders["cart spider"].price
    cart_spider_winner = Spiders["cart spider"].winner

    condition1 = (darkback_price == PRICES["$60"] and cart_spider_winner == "Vicky")
    condition2 = (cart_spider_price == PRICES["$60"] and darkback_winner == "Vicky")

    return condition1 or condition2

def clue2(Prices, Winners, Spiders):
    """Of the spider that sold for $75 and Shelley's purchase, one was the archaenido and the other was the cart spider."""
    spider_75_name = Prices[PRICES["$75"]].spider
    shelley_spider_name = Winners["Shelley"].spider

    condition1 = (spider_75_name == "archaenido" and shelley_spider_name == "cart spider")
    condition2 = (spider_75_name == "cart spider" and shelley_spider_name == "archaenido")

    return condition1 or condition2

def clue3(Prices, Winners, Spiders):
    """The arachnid that sold for $90 was either Shelley's purchase or the darkback."""
    spider_90_name = Prices[PRICES["$90"]].spider
    shelley_spider_name = Winners["Shelley"].spider

    return spider_90_name == shelley_spider_name or spider_90_name == "darkback"

def verify(grid):
    total_clues = 4

    # Defensive handling for malformed input
    if not isinstance(grid, list) or not all(isinstance(row, list) and len(row) == 3 for row in grid):
        return (0.0, list(range(total_clues)))

    try:
        # Parse grid into useful maps
        prices_map = {}
        winners_map = {}
        spiders_map = {}

        for row in grid:
            price_str, winner_name, spider_name = row
            price_val = PRICES.get(price_str)

            if price_val is None:
                return (0.0, list(range(total_clues))) # Missing required price value

            # Populate maps
            prices_map[price_val] = Price(value=price_val, winner=winner_name, spider=spider_name)
            winners_map[winner_name] = Winner(name=winner_name, price=price_val, spider=spider_name)
            spiders_map[spider_name] = Spider(name=spider_name, price=price_val, winner=winner_name)

        # Check for expected keys in maps (e.g., all winners, spiders, prices are present)
        expected_winners = {"Charles", "Freddie", "Shelley", "Vicky"}
        expected_spiders = {"archaenido", "cart spider", "darkback", "whip spider"}
        expected_prices_values = set(PRICES.values())

        if not (expected_winners == set(winners_map.keys()) and
                expected_spiders == set(spiders_map.keys()) and
                expected_prices_values == set(prices_map.keys())):
            return (0.0, list(range(total_clues)))

    except (KeyError, AttributeError, TypeError):
        return (0.0, list(range(total_clues)))

    clue_functions = [
        clue0,
        clue1,
        clue2,
        clue3,
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(prices_map, winners_map, spiders_map))
        except (KeyError, AttributeError):
            # If a clue function fails due to missing data (e.g., a key not found),
            # it means the grid is malformed or incomplete for that clue.
            # Treat as failed, but the initial parsing should catch most of these.
            clue_results.append(False)

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    satisfied_clues = sum(1 for ok in clue_results if ok)
    reward = float(satisfied_clues) / total_clues

    return reward, failed_clues

