from dataclasses import dataclass

# Define categories and their possible values
CALORIES = {
    "345": 345,
    "360": 360,
    "375": 375,
    "390": 390,
}

DAYS_ORDER = {
    "Wednesday": 0,
    "Thursday": 1,
    "Friday": 2,
    "Saturday": 3,
}

@dataclass
class Snack:
    name: str
    calories: int = None
    day: str = None

@dataclass
class Day:
    name: str
    calories: int = None
    snack: str = None

@dataclass
class Calorie:
    value: int
    snack: str = None
    day: str = None

# Clue functions
def clue0(Snacks, Days, Calories):
    # 1.The almond energy bar contains somewhat fewer calories than the snack given out on Wednesday.
    almond_bar_calories = Snacks["almond energy bar"].calories
    wednesday_snack_calories = Days["Wednesday"].calories
    return almond_bar_calories < wednesday_snack_calories

def clue1(Snacks, Days, Calories):
    # 2.The snack given out on Thursday contains 15 fewer calories than the oatmeal cookie.
    thursday_snack_calories = Days["Thursday"].calories
    oatmeal_cookie_calories = Snacks["oatmeal cookie"].calories
    return thursday_snack_calories == oatmeal_cookie_calories - 15

def clue2(Snacks, Days, Calories):
    # 3.The recipe given out on Friday contains somewhat fewer calories than the granola mix.
    friday_snack_calories = Days["Friday"].calories
    granola_mix_calories = Snacks["granola mix"].calories
    return friday_snack_calories < granola_mix_calories

def clue3(Snacks, Days, Calories):
    # 4.The snack given out on Saturday contains 15 more calories than the snack given out on Thursday.
    saturday_snack_calories = Days["Saturday"].calories
    thursday_snack_calories = Days["Thursday"].calories
    return saturday_snack_calories == thursday_snack_calories + 15

def clue4(Snacks, Days, Calories):
    # 5.The snack with 360 calories was either the one given out on Wednesday or the granola mix.
    snack_360_name = Calories[360].snack
    return snack_360_name == Days["Wednesday"].snack or snack_360_name == "granola mix"

def verify(grid):
    # Total number of clues
    total_clues = 5

    # Initialize data structures for parsing
    Snacks = {}
    Days = {}
    Calories_map = {} # Renamed to avoid conflict with CALORIES constant

    # Expected entities for validation
    expected_snacks = {"almond energy bar", "oatmeal cookie", "granola mix", "trail mix"}
    expected_days = {"Wednesday", "Thursday", "Friday", "Saturday"}
    expected_calories = {345, 360, 375, 390}

    # Sets to track seen values for uniqueness checks
    seen_snacks = set()
    seen_days = set()
    seen_calories = set()

    # Parse the grid
    try:
        if not (isinstance(grid, list) and len(grid) == 4):
            return 0.0, list(range(total_clues))

        for row in grid:
            if not (isinstance(row, list) and len(row) == 3):
                return 0.0, list(range(total_clues))

            calorie_str, snack_name, day_name = row

            # Validate and convert calorie value
            if calorie_str not in CALORIES:
                return 0.0, list(range(total_clues))
            calorie_value = CALORIES[calorie_str]

            # Check for missing or invalid entities
            if snack_name not in expected_snacks or day_name not in expected_days:
                return 0.0, list(range(total_clues))

            # Check for uniqueness within categories
            if snack_name in seen_snacks or day_name in seen_days or calorie_value in seen_calories:
                return 0.0, list(range(total_clues))

            seen_snacks.add(snack_name)
            seen_days.add(day_name)
            seen_calories.add(calorie_value)

            # Populate data structures
            Snacks[snack_name] = Snack(name=snack_name, calories=calorie_value, day=day_name)
            Days[day_name] = Day(name=day_name, calories=calorie_value, snack=snack_name)
            Calories_map[calorie_value] = Calorie(value=calorie_value, snack=snack_name, day=day_name)

        # Final check for all entities being present
        if not (len(seen_snacks) == len(expected_snacks) and
                len(seen_days) == len(expected_days) and
                len(seen_calories) == len(expected_calories)):
            return 0.0, list(range(total_clues))

    except Exception:
        # Catch any other parsing errors
        return 0.0, list(range(total_clues))

    # List of clue functions
    clue_functions = [
        clue0,
        clue1,
        clue2,
        clue3,
        clue4,
    ]

    # Evaluate all clues
    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(Snacks, Days, Calories_map))
        except Exception:
            # If a clue function fails due to missing data (should be caught by parsing)
            # or unexpected error, consider it failed.
            clue_results.append(False)

    # Calculate reward and failed clues
    satisfied_clues = sum(1 for result in clue_results if result)
    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    reward = float(satisfied_clues) / total_clues
    return reward, failed_clues

