    return Customers["Michael"].price == Superfoods["chia seeds"].price - 2.0

def clue5(Customers, Superfoods):
    # 6. James paid $8.50.
    return Customers["James"].price == PRICES["$8.50"]

def clue6(Customers, Superfoods):
    # 7. Of the customer who paid $9.50 and the customer who paid $7.50, one asked for flax seeds and the other is Emily.

    customer_9_50_name = None
    customer_7_50_name = None

    for customer_name, customer_obj in Customers.items():
        if customer_obj.price == PRICES["$9.50"]:
            customer_9_50_name = customer_name
        if customer_obj.price == PRICES["$7.50"]:
            customer_7_50_name = customer_name

    if customer_9_50_name is None or customer_7_50_name is None:
        return False # Malformed grid, prices not found

    # Check the conditions:
    # (customer_9_50_name ordered flax seeds AND customer_7_50_name is Emily)
    # OR
    # (customer_7_50_name ordered flax seeds AND customer_9_50_name is Emily)

    cond1 = (Customers[customer_9_50_name].superfood == "flax seeds" and customer_7_50_name == "Emily")
    cond2 = (Customers[customer_7_50_name].superfood == "flax seeds" and customer_9_50_name == "Emily")

    return cond1 or cond2

def verify(grid):
    customers_data = {}
    superfoods_data = {}
    prices_to_customer = {}
    prices_to_superfood = {}

    all_prices = set(PRICES.values())
    all_customers = {"Emily", "Michael", "James", "Olivia", "Sarah"}
    all_superfoods = {"quinoa", "chia seeds", "kale", "spinach", "flax seeds"}

    # Defensive check for grid structure and content
    if not isinstance(grid, list) or not all(isinstance(row, list) and len(row) == 3 for row in grid):
        return 0.0, list(range(7)) # Total 7 clues

    if len(grid) != len(all_prices):
        return 0.0, list(range(7))

    try:
        for row in grid:
            price_str, customer_name, superfood_name = row

            price_val = PRICES.get(price_str)
            if price_val is None:
                return 0.0, list(range(7))

            if customer_name not in all_customers or superfood_name not in all_superfoods:
                return 0.0, list(range(7))

            # Check for uniqueness within the grid
            if customer_name in customers_data or superfood_name in superfoods_data or \
               price_val in prices_to_customer or price_val in prices_to_superfood:
                return 0.0, list(range(7)) # Duplicate assignment

            customers_data[customer_name] = Customer(name=customer_name, price=price_val, superfood=superfood_name)
            superfoods_data[superfood_name] = Superfood(name=superfood_name, price=price_val, customer=customer_name)
            prices_to_customer[price_val] = customer_name
            prices_to_superfood[price_val] = superfood_name

        # Ensure all entities are present
        if len(customers_data) != len(all_customers) or \
           len(superfoods_data) != len(all_superfoods) or \
           len(prices_to_customer) != len(all_prices):
            return 0.0, list(range(7))

    except (ValueError, KeyError, TypeError):
        return 0.0, list(range(7)) # Malformed input

    clue_functions = [
        clue0,
        clue1,
        clue2,
        clue3,
        clue4,
        clue5,
        clue6,
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(customers_data, superfoods_data))
        except (KeyError, AttributeError):
            # This can happen if a clue tries to access a non-existent entity due to malformed input
            # or if the parsing logic above missed something.
            return 0.0, list(range(len(clue_functions)))

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    total_clues = len(clue_results)
    satisfied_clues = sum(clue_results)

    return float(satisfied_clues) / total_clues, failed_clues

