    mystery_novel_buyer_name = Books["mystery novel"].name
    return (
        Names[mystery_novel_buyer_name].genre == "fantasy"
        or Names[mystery_novel_buyer_name].genre == "science fiction"
    )

def clue2(Prices, Names, Genres, Books):
