            set(Books_map.keys()) == expected_books and
            set(Prices_map.keys()) == expected_prices_values):
        return 0.0, list(range(7))

    clue_functions = [
        clue0,
        clue1,
        clue2,
        clue3,
        clue4,
        clue5,
        clue6,
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(Prices_map, Names_map, Genres_map, Books_map))
        except Exception:
            # If any clue function fails due to missing data (e.g., a key not found
            # that should have been caught by initial parsing), mark all as failed.
            return 0.0, list(range(len(clue_functions)))

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    total_clues = len(clue_results)
    satisfied_clues = sum(clue_results)

    return float(satisfied_clues) / total_clues, failed_clues

