def verify(grid):
    # Check for valid grid structure and content
    if not isinstance(grid, list) or not all(isinstance(row, list) and len(row) == 4 for row in grid):
        return (0.0, list(range(10))) # 10 clues total

    # Ensure all required years are present and unique
    present_years = set()
    for row in grid:
        if row[0] not in YEARS:
            return (0.0, list(range(10)))
        present_years.add(row[0])
    if len(present_years) != len(YEARS):
        return (0.0, list(range(10)))

    # Parse grid into useful maps
    Athletes = {}
    Teams = {}
    Hometowns = {}

    try:
        for row in grid:
            year_str, athlete_name, team_name, hometown_name = row
            year_idx = YEARS[year_str]

            # Populate Athletes map
            if athlete_name in Athletes: # Duplicate athlete
                return (0.0, list(range(10)))
            Athletes[athlete_name] = Athlete(name=athlete_name, year=year_idx, team=team_name, hometown=hometown_name)

            # Populate Teams map
            if team_name in Teams: # Duplicate team
                return (0.0, list(range(10)))
            Teams[team_name] = Team(name=team_name, year=year_idx, athlete=athlete_name, hometown=hometown_name)

            # Populate Hometowns map
            if hometown_name in Hometowns: # Duplicate hometown
                return (0.0, list(range(10)))
            Hometowns[hometown_name] = Hometown(name=hometown_name, year=year_idx, athlete=athlete_name, team=team_name)
    except (KeyError, TypeError):
        # Handle cases where values might be missing or malformed
        return (0.0, list(range(10)))

    # Check for expected number of entities
    expected_athletes = {"Adam", "Jackie", "Marcus", "Taylor", "Walter"}
    expected_teams = {"Phillies", "Nationals", "Rockies", "Giants", "Brewers"}
    expected_hometowns = {"Cedar Grove", "Franklin", "Lakeview", "Riverside", "Jacumba"}

    if not (set(Athletes.keys()) == expected_athletes and
            set(Teams.keys()) == expected_teams and
            set(Hometowns.keys()) == expected_hometowns):
        return (0.0, list(range(10)))

    # List of clue functions
    clue_functions = [
        clue0, clue1, clue2, clue3, clue4,
        clue5, clue6, clue7, clue8, clue9,
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(Athletes, Teams, Hometowns, YEARS))
        except Exception:
            # If a clue function raises an error, it means the grid is invalid for that clue
            clue_results.append(False)

    total_clues = len(clue_results)
    satisfied_clues = sum(1 for result in clue_results if result)
    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    reward = float(satisfied_clues) / total_clues if total_clues > 0 else 0.0
    return (reward, failed_clues)
