ALL_FACEBOOK_FRIENDS = set(FACEBOOK_FRIENDS_VALUES.values())
ALL_NAMES = {"Adam", "Charlie", "Mary", "Tom", "Neil"}
ALL_LINKEDIN_CONNECTIONS = set(LINKEDIN_CONNECTIONS_VALUES.values())
ALL_TWITTER_FOLLOWERS = set(TWITTER_FOLLOWERS_VALUES.values())

@dataclass
