    person_200_fb = Facebook[200].person
    person_85_li = LinkedIn[85].person
    person_720_tw = Twitter[720].person
    return (person_200_fb == person_85_li) or (person_200_fb == person_720_tw)

def clue1(People, Facebook, LinkedIn, Twitter):
