    person_600_tw = Twitter[600].person
    person_100_fb = Facebook[100].person
    person_200_fb = Facebook[200].person
    return (person_600_tw == person_100_fb) or (person_600_tw == person_200_fb)

def clue6(People, Facebook, LinkedIn, Twitter):
    # Adam is either the person with 200 Facebook friends or the person with 50 LinkedIn connections.
    return ("Adam" == Facebook[200].person) or ("Adam" == LinkedIn[50].person)

def clue7(People, Facebook, LinkedIn, Twitter):
