    return Twitter[620].facebook_friends == Twitter[720].facebook_friends - 30

def clue10(People, Facebook, LinkedIn, Twitter):
    # Of Tom and the person with 900 Twitter followers, one has 50 LinkedIn connections and the other has 100 Facebook friends.
    person_tom_obj = People["Tom"]
    person_900_tw_name = Twitter[900].person
    person_900_tw_obj = People[person_900_tw_name]

    # The two people must be distinct for the "one... and the other" phrasing to apply.
    if person_tom_obj.name == person_900_tw_obj.name:
        return False

    cond1 = (person_tom_obj.linkedin_connections == 50 and person_900_tw_obj.facebook_friends == 100)
    cond2 = (person_900_tw_obj.linkedin_connections == 50 and person_tom_obj.facebook_friends == 100)
