def verify(grid):
    total_clues = 11

    people_map = {}
    facebook_map = {}
    linkedin_map = {}
    twitter_map = {}

    # Expected number of rows and columns
    expected_rows = 5
    expected_cols = 4

    if not isinstance(grid, list) or len(grid) != expected_rows:
        return 0.0, list(range(total_clues))

    seen_facebook = set()
    seen_names = set()
    seen_linkedin = set()
    seen_twitter = set()

    for r_idx, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != expected_cols:
            return 0.0, list(range(total_clues))

        fb_str, name_str, li_str, tw_str = row

        try:
            # Validate and convert Facebook Friends
            if fb_str not in FACEBOOK_FRIENDS_VALUES:
                return 0.0, list(range(total_clues))
            fb_int = FACEBOOK_FRIENDS_VALUES[fb_str]
            if fb_int in seen_facebook: # Check for uniqueness
                return 0.0, list(range(total_clues))
            seen_facebook.add(fb_int)

            # Validate Name
            if name_str not in ALL_NAMES:
                return 0.0, list(range(total_clues))
            if name_str in seen_names: # Check for uniqueness
                return 0.0, list(range(total_clues))
            seen_names.add(name_str)

            # Validate and convert LinkedIn Connections
            if li_str not in LINKEDIN_CONNECTIONS_VALUES:
                return 0.0, list(range(total_clues))
            li_int = LINKEDIN_CONNECTIONS_VALUES[li_str]
            if li_int in seen_linkedin: # Check for uniqueness
                return 0.0, list(range(total_clues))
            seen_linkedin.add(li_int)

            # Validate and convert Twitter Followers
            if tw_str not in TWITTER_FOLLOWERS_VALUES:
                return 0.0, list(range(total_clues))
            tw_int = TWITTER_FOLLOWERS_VALUES[tw_str]
            if tw_int in seen_twitter: # Check for uniqueness
                return 0.0, list(range(total_clues))
            seen_twitter.add(tw_int)
        except (ValueError, KeyError): # Catch potential errors during conversion/lookup
            return 0.0, list(range(total_clues))

        # Populate dataclasses
        person_obj = Person(name=name_str, facebook_friends=fb_int,
                            linkedin_connections=li_int, twitter_followers=tw_int)
        facebook_obj = Facebook(count=fb_int, person=name_str,
                                linkedin_connections=li_int, twitter_followers=tw_int)
        linkedin_obj = LinkedIn(count=li_int, person=name_str,
                                facebook_friends=fb_int, twitter_followers=tw_int)
        twitter_obj = Twitter(count=tw_int, person=name_str,
                              facebook_friends=fb_int, linkedin_connections=li_int)

        people_map[name_str] = person_obj
        facebook_map[fb_int] = facebook_obj
        linkedin_map[li_int] = linkedin_obj
        twitter_map[tw_int] = twitter_obj

    # Final check for completeness (all expected values must be present)
    if not (seen_facebook == ALL_FACEBOOK_FRIENDS and
            seen_names == ALL_NAMES and
            seen_linkedin == ALL_LINKEDIN_CONNECTIONS and
            seen_twitter == ALL_TWITTER_FOLLOWERS):
        return 0.0, list(range(total_clues))

    clue_functions = [
        clue0, clue1, clue2, clue3, clue4,
        clue5, clue6, clue7, clue8, clue9,
        clue10
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(people_map, facebook_map, linkedin_map, twitter_map))
        except KeyError: # If a clue tries to access a non-existent key (e.g., due to malformed input not caught earlier)
            return 0.0, list(range(total_clues))

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    reward = float(sum(clue_results)) / total_clues
    return reward, failed_clues

