from dataclasses import dataclass

# Mappings for categories to numerical or standardized values
ELEVATIONS = {
    "2,000 m": 2000,
    "2,200 m": 2200,
    "2,500 m": 2500,
    "3,000 m": 3000,
    "3,500 m": 3500,
}

YEARS = {
    "1998": 1998,
    "2005": 2005,
    "2008": 2008,
    "2010": 2010,
    "2004": 2004,
}

# Define dataclasses for each entity type to hold its attributes
@dataclass
class Peak:
    name: str
    elevation: int = None
    continent: str = None
    year: int = None

@dataclass
class Continent:
    name: str
    elevation: int = None
    peak: str = None
    year: int = None

@dataclass
class Year:
    value: int
    elevation: int = None
    peak: str = None
    continent: str = None

# Clue functions
# Each function takes dictionaries of parsed entities and returns True if the clue is satisfied, False otherwise.

# 1. Cerbel was not recorded in 2005.
def clue0(Peaks, Years):
    return Peaks["Cerbel"].year != YEARS["2005"]

# 2. Of the mountain Mira recorded in 2005 and Irskela, one is in Africa and the other is 3,000 meters high.
def clue1(Peaks, Years, Continents):
    peak_2005 = Years[YEARS["2005"]].peak
    irskela_peak = "Irskela"

    is_2005_africa = Peaks[peak_2005].continent == "Africa"
    is_2005_3000m = Peaks[peak_2005].elevation == ELEVATIONS["3,000 m"]

    is_irskela_africa = Peaks[irskela_peak].continent == "Africa"
    is_irskela_3000m = Peaks[irskela_peak].elevation == ELEVATIONS["3,000 m"]

    # One is in Africa AND the other is 3,000 meters high.
    # This means (2005_peak is Africa AND Irskela is 3000m) OR (Irskela is Africa AND 2005_peak is 3000m)
    return (is_2005_africa and is_irskela_3000m) or (is_irskela_africa and is_2005_3000m)

# 3. Garray is either the 3,000-meter peak or the mountain Mira recorded in 1998.
def clue2(Peaks, Years):
    peak_3000m = None
    for peak_name, peak_obj in Peaks.items():
        if peak_obj.elevation == ELEVATIONS["3,000 m"]:
            peak_3000m = peak_name
            break

    peak_1998 = Years[YEARS["1998"]].peak

    return Peaks["Garray"].name == peak_3000m or Peaks["Garray"].name == peak_1998

# 4. Sihat is 500 meters taller than the mountain Mira recorded in 2005.
def clue3(Peaks, Years):
    peak_2005_elevation = Years[YEARS["2005"]].elevation
    return Peaks["Sihat"].elevation == peak_2005_elevation + 500

# 5. The five mountains are the 2,500-meter peak, the mountain Mira recorded in 2010, the mountain located in Asia, the mountain located in Europe and the mountain in South America.
def clue4(Peaks, Years, Continents):
    # Collect the names of the peaks described in the clue
    peak_2500m = None
    for peak_name, peak_obj in Peaks.items():
        if peak_obj.elevation == ELEVATIONS["2,500 m"]:
            peak_2500m = peak_name
            break

    peak_2010 = Years[YEARS["2010"]].peak
    peak_asia = Continents["Asia"].peak
    peak_europe = Continents["Europe"].peak
    peak_south_america = Continents["South America"].peak

    # Put them in a set to check for uniqueness and count
    described_peaks = {peak_2500m, peak_2010, peak_asia, peak_europe, peak_south_america}

    # Check if all 5 are distinct and correspond to the 5 actual peaks
    # The problem implies these are the *names* of the five mountains.
    # So, we check if the set of described peaks matches the set of all peak names.
    all_peak_names = set(Peaks.keys())

    return described_peaks == all_peak_names and len(described_peaks) == 5

# 6. Sihat is somewhat taller than the mountain located in Australia.
def clue5(Peaks, Continents):
    australia_peak_elevation = Continents["Australia"].elevation
    return Peaks["Sihat"].elevation > australia_peak_elevation

# 7. The mountain Mira recorded in 2008 is not in Europe.
def clue6(Peaks, Years):
    peak_2008_continent = Years[YEARS["2008"]].continent
    return peak_2008_continent != "Europe"

# 8. The mountain located in Asia is 500 meters higher than the mountain Mira recorded in 2005.
def clue7(Peaks, Years, Continents):
    asia_peak_elevation = Continents["Asia"].elevation
    peak_2005_elevation = Years[YEARS["2005"]].elevation
    return asia_peak_elevation == peak_2005_elevation + 500


def verify(grid):
