            Years_map[year] = Year(value=year, elevation=elevation, peak=name, continent=continent)

        # Ensure all expected entities are present
        if len(Peaks) != expected_rows or len(Continents) != expected_rows or len(Years_map) != expected_rows:
             return (0.0, list(range(8)))
