            elif i == 5: # clue5(Peaks, Continents)
                clue_results.append(clue_func(Peaks, Continents))
            elif i == 6: # clue6(Peaks, Years)
                clue_results.append(clue_func(Peaks, Years_map))
            elif i == 7: # clue7(Peaks, Years, Continents)
                clue_results.append(clue_func(Peaks, Years_map, Continents))
            else:
                clue_results.append(False) # Should not happen
        except Exception:
            # If any clue function raises an error, it means the grid is invalid for that clue
            clue_results.append(False)

    total_clues = len(clue_functions)
    satisfied_clues = sum(1 for result in clue_results if result)
    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    reward = float(satisfied_clues) / total_clues
    return reward, failed_clues

