# Helper to parse string speeds like "Mach 18" to "Mach 1.8"
def parse_speed_string(s):
    if s.startswith("Mach "):
        try:
            # Handle "Mach 18" -> "Mach 1.8"
            if len(s) == 8 and s[5:].isdigit(): # e.g., "Mach 18"
                return float(s[5]) + float(s[6:]) / 10.0
            return float(s[5:])
        except ValueError:
            pass
    return None

