    # Initialize dictionaries for parsing
    Aircrafts = {}
    Companies = {}
    Prices_map = {} # Renamed to avoid conflict with PRICES constant
    TopSpeeds_map = {} # Renamed to avoid conflict with TOP_SPEEDS constant

    try:
        for row in grid:
            if not isinstance(row, list) or len(row) != expected_num_cols:
                return 0.0, list(range(12))

            price_str, aircraft_name, company_name, top_speed_str = row

            # Parse and validate values
