            if price_val is None:
                return 0.0, list(range(12))

            top_speed_val = parse_speed_string(top_speed_str)
            # Check if the parsed speed is one of the expected values
            if top_speed_val not in TOP_SPEEDS.values():
                return 0.0, list(range(12))

            # Populate Aircrafts map
            if aircraft_name in Aircrafts: # Check for duplicates
                return 0.0, list(range(12))
            Aircrafts[aircraft_name] = Aircraft(
                name=aircraft_name,
                price=price_val,
                company=company_name,
                top_speed=top_speed_val
            )

            # Populate Companies map
            if company_name in Companies: # Check for duplicates
                return 0.0, list(range(12))
            Companies[company_name] = Company(
                name=company_name,
                price=price_val,
                aircraft=aircraft_name,
                top_speed=top_speed_val
            )

            # Populate Prices map
            if price_val in Prices_map: # Check for duplicates
                return 0.0, list(range(12))
            Prices_map[price_val] = Price(
                value=price_val,
                aircraft=aircraft_name,
                company=company_name,
                top_speed=top_speed_val
            )

            # Populate TopSpeeds map
            if top_speed_val in TopSpeeds_map: # Check for duplicates
                return 0.0, list(range(12))
            TopSpeeds_map[top_speed_val] = TopSpeed(
                value=top_speed_val,
                aircraft=aircraft_name,
                company=company_name,
                price=price_val
            )

        # Ensure all expected entities are present and unique
        if len(Aircrafts) != expected_num_rows or \
           len(Companies) != expected_num_rows or \
           len(Prices_map) != expected_num_rows or \
           len(TopSpeeds_map) != expected_num_rows:
            return 0.0, list(range(12))

    except Exception: # Catch any other parsing errors
        return 0.0, list(range(12))

    clue_functions = [
        clue0, clue1, clue2, clue3, clue4, clue5,
        clue6, clue7, clue8, clue9, clue10, clue11
    ]

    clue_results = [
        func(Aircrafts, Prices_map, Companies, TopSpeeds_map)
        for func in clue_functions
    ]

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    total_clues = len(clue_results)
    satisfied_clues = sum(clue_results)

    return float(satisfied_clues) / total_clues, failed_clues

