    return ineoch_woodworker.price < johnnie_entry.price

def clue12(data):
    # 13.Larry charges 4 dollars more than the carver who works with pine.
    larry_entry = data.get_by_woodworker("Larry")
    pine_woodworker = data.get_by_wood("pine")

    if larry_entry is None or pine_woodworker is None:
        return False

    return larry_entry.price == pine_woodworker.price + 4

class GridData:
    def __init__(self, grid):
        self.entries = []
        self.by_price = {}
        self.by_woodworker = {}
        self.by_wood = {}
        self.by_character = {}

        # Check for duplicate values within categories
        seen_prices = set()
        seen_woodworkers = set()
        seen_woods = set()
        seen_characters = set()

        for row in grid:
            if len(row) != 4:
                raise ValueError("Each row must have 4 elements.")

            price_str, woodworker, wood, character = row

            try:
                price = parse_dollars(price_str)
            except (ValueError, AttributeError):
                raise ValueError(f"Invalid price format: {price_str}")

            if price not in PRICES.values():
                raise ValueError(f"Price '{price_str}' not in allowed prices.")
            if woodworker not in WOODWORKERS:
                raise ValueError(f"Woodworker '{woodworker}' not in allowed woodworkers.")
            if wood not in WOODS:
                raise ValueError(f"Wood '{wood}' not in allowed woods.")
            if character not in CHARACTERS:
                raise ValueError(f"Character '{character}' not in allowed characters.")

            # Check for uniqueness within categories
            if price in seen_prices:
                raise ValueError(f"Duplicate price found: {price_str}")
            seen_prices.add(price)
            if woodworker in seen_woodworkers:
                raise ValueError(f"Duplicate woodworker found: {woodworker}")
            seen_woodworkers.add(woodworker)
            if wood in seen_woods:
                raise ValueError(f"Duplicate wood found: {wood}")
            seen_woods.add(wood)
            if character in seen_characters:
                raise ValueError(f"Duplicate character found: {character}")
            seen_characters.add(character)

            entry = Entry(price, woodworker, wood, character)
            self.entries.append(entry)
            self.by_price[price] = entry
            self.by_woodworker[woodworker] = entry
            self.by_wood[wood] = entry
            self.by_character[character] = entry

        # Ensure all categories are fully populated
        if not (len(self.by_price) == len(PRICES) and
                len(self.by_woodworker) == len(WOODWORKERS) and
                len(self.by_wood) == len(WOODS) and
                len(self.by_character) == len(CHARACTERS)):
            raise ValueError("Grid does not contain all required entries for one or more categories.")

    def get_by_price(self, price):
        return self.by_price.get(price)

    def get_by_woodworker(self, woodworker):
        return self.by_woodworker.get(woodworker)

    def get_by_wood(self, wood):
        return self.by_wood.get(wood)

    def get_by_character(self, character):
        return self.by_character.get(character)

def verify(grid):
    clue_functions = [
        clue0, clue1, clue2, clue3, clue4, clue5, clue6, clue7, clue8, clue9, clue10, clue11, clue12
    ]
    total_clues = len(clue_functions)

    try:
        data = GridData(grid)
    except ValueError:
        return 0.0, list(range(total_clues))

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(data))
        except (KeyError, AttributeError): # Handle cases where a clue might try to access a non-existent item due to malformed input not caught by initial parsing
            clue_results.append(False)

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    reward = float(sum(clue_results)) / total_clues
    return reward, failed_clues
